// ---------------------------------------------------------------------------------------- ибам ---

/** еКщЦВЕИ АМ щМАР ТЯАПЕФИЙЭР КОЦАЯИАСЛЭР ибам ЕъМАИ ЕККГМИЙЭР ЙАИ щЦЙУЯОР.
 * @param string $iban о КОЦАЯИАСЛЭР ибам
 * @return string о КОЦАЯИАСЛЭР IBAN АМ ЕъМАИ ЕККГМИЙЭР ЙАИ щЦЙУЯОР, АККИЧР ПУЯОДОТЕъ СЖэКЛА */
function iban($iban) {
	$iban = str_replace(' ', '', $iban);
	if (is_greek_iban($iban) && is_valid_iban($iban)) return $iban;
	trigger_error($iban ? "тО IBAN '<b>$iban</b>' ДЕМ ЕъМАИ ЕККГМИЙЭ ЙАИ щЦЙУЯО" : 'дЕМ ДЧХГЙЕ щЦЙУЯО ЕККГМИЙЭ ибам');
}

/** еКщЦВЕИ АМ щМАР ТЯАПЕФИЙЭР КОЦАЯИАСЛЭР ибам СУЛЖЫМЕъ ЛЕ ТО ЕККГМИЙЭ ПЯЭТУПО.
 * дЕМ ЙэМЕИ щКЕЦВО ЕЦЙУЯЭТГТАР СТОМ IBAN. аПКэ ЕКщЦВЕИ АМ ТА ЬГЖъА ТОУ СУЛЖЫМОЩМ ЛЕ АУТэ ПОУ щВОУМ
 * ЙАХОЯИСТЕъ ЦИА ТОУР ЕККГМИЙОЩР IBAN.
 * @param string $iban о КОЦАЯИАСЛЭР ибам ВЫЯъР ЙЕМэ, ЛЭМО ЛЕ ВАЯАЙТчЯЕР 0-9а-ф
 * @return bool о КОЦАЯИАСЛЭР IBAN ЕъМАИ ЕККГМИЙЭР АККэ ПИХАМЭМ ЛГ щЦЙУЯОР */
function is_greek_iban($iban) { return preg_match('/GR\d{25}/', $iban); }

/** еКщЦВЕИ АМ щМАР ТЯАПЕФИЙЭР КОЦАЯИАСЛЭР ибам СУЛЖЫМЕъ ЛЕ ТО ЦЕМИЙЭ ПЯЭТУПО.
 * дЕМ ЙэМЕИ щКЕЦВО ЕЦЙУЯЭТГТАР СТОМ IBAN. аПКэ ЕКщЦВЕИ АМ ТА ЬГЖъА ТОУ СУЛЖЫМОЩМ ЛЕ АУТэ ПОУ щВОУМ
 * ЙАХОЯИСТЕъ ЦИА ТОУР IBAN.
 * @param string $iban о КОЦАЯИАСЛЭР ибам ВЫЯъР ЙЕМэ, ЛЭМО ЛЕ ВАЯАЙТчЯЕР 0-9а-ф
 * @return bool еъМАИ КОЦАЯИАСЛЭР IBAN, АККэ ПИХАМЭМ ЛГ щЦЙУЯОР */
function is_iban($iban) { return preg_match('/[A-Z]{2}\d{2}[A-Z0-9]{1,30}/', $iban); }

/** еКщЦВЕИ АМ щМАР ТЯАПЕФИЙЭР КОЦАЯИАСЛЭР ибам ЕъМАИ щЦЙУЯОР.
 * пЯИМ ТГМ ЕЙТщКЕСГ, ХА ПЯщПЕИ щМАР АПЭ ТОУР is_iban(), is_greek_iban() МА щВЕИ ЕПИСТЯщЬЕИ true.
 * <p>╦МАР КОЦАЯИАСЛЭР IBAN АПОТЕКЕъТАИ:
 * <ul><li>аПЭ 2 ЙЕЖАКАъА КАТИМИЙэ ЦЯэЛЛАТА (а-ф) ТГР ВЧЯАР. сТГМ еККэДА GR.
 * <li>аПЭ 2 АЯИХЛОЩР (0-9) ЕКщЦВОУ ЕЦЙУЯЭТГТАР.
 * <li>лщВЯИ 30 ВАЯАЙТчЯЕР, АЯИХЛОЩР ч ЙЕЖАКАъА КАТИМИЙэ ЦЯэЛЛАТА (0-9 а-ф) ПОУ ЙАХОЯъФОМТАИ
 * ДИАЖОЯЕТИЙэ СЕ ЙэХЕ ВЧЯА ЙАИ АПОТЕКОЩМ ТОМ Basic Bank Account Number (BBAN). сТГМ еККэДА
 *  СУЦЙЕЙЯИЛщМА ЕъМАИ 23 АЯИХЛОъ (0-9):
 * <ul><li>аПЭ 3 АЯИХЛОЩР (0-9) ПОУ ДГКЧМОУМ ТГМ ТЯэПЕФА.
 * <li>аПЭ 4 АЯИХЛОЩР (0-9) ПОУ ДГКЧМОУМ ТО УПОЙАТэСТГЛА ТГР ТЯэПЕФАР.
 * <li>аПЭ 16 АЯИХЛОЩР (0-9) ПОУ ДГКЧМОУМ ТО КОЦАЯИАСЛЭ СТГМ ТЯэПЕФА.</ul></ul>
 * <p>о АЯИХЛЭР ЕКщЦВОУ ЕЦЙУЯЭТГТАР ПЯОЙЩПТЕИ ЫР ЕНчР:
 * <ul><li>дГЛИОУЯЦОЩЛЕ щМАМ ЙЕъЛЕМО ПОУ АПОТЕКЕъТАИ АПЭ ТОМ BBAN, ТОМ ЙЫДИЙЭ ТГР ВЧЯАР ЙАИ ТО '00'
 * ПОУ АМТИЙАХИСТэ ТОУР АЯИХЛОЩР ЕКщЦВОУ ЕЦЙУЯЭТГТАР ПОУ ДЕМ щВОУЛЕ УПОКОЦъФЕИ АЙЭЛА. дГКАДч ПэЛЕ
 * ТОУР ПЯЧТОУР 4 ВАЯАЙТчЯЕР ТОУ ибам СТО ТщКОР ЙАИ ЦИА АЯИХЛОЩР ЕКщЦВОУ ЕЦЙУЯЭТГТАР БэФОУЛЕ '00'.
 * <li>лЕТАТЯщПОУЛЕ ЙэХЕ ЦЯэЛЛА ТОУ ЙЕИЛщМОУ СЕ ДИЬчЖИО АЯИХЛЭ, АЖАИЯЧМТАР АПЭ ТОМ ASCII ВАЯАЙТчЯА
 * ТО 55. ╦ТСИ ЙэХЕ ВАЯАЙТчЯАР НЕЙИМэЕИ АПЭ ТО 10.
 * <li>уПОКОЦъФОУЛЕ ТО УПЭКОИПО ТГР ДИАъЯЕСГР ТОУ ПАЯАПэМЫ ЙЕИЛщМОУ, ПОУ ПКщОМ ЕъМАИ АЯИХЛЭР, АПЭ ТО
 * 97.
 * <li>аЖАИЯОЩЛЕ ТО УПЭКОИПО ТГР ДИАъЯЕСГР ПОУ БЯчЙАЛЕ ПАЯАПэМЫ АПЭ ТО 98.
 * <li>тО АПОТщКЕСЛА ЕъМАИ О АЯИХЛЭР ЕКщЦВОУ ЕЦЙУЯЭТГТАР.</ul>
 * <p>о щКЕЦВОР ЕЦЙУЯЭТГТАР ПЯАЦЛАТОПОИЕъТАИ ЫР ЕНчР:
 * <ul><li>дГЛИОУЯЦОЩЛЕ щМАМ ЙЕъЛЕМО ПОУ АПОТЕКЕъТАИ АПЭ ТОМ BBAN, ТОМ ЙЫДИЙЭ ТГР ВЧЯАР ЙАИ ТОУР
 * АЯИХЛОЩР ЕКщЦВОУ ЕЦЙУЯЭТГТАР. дГКАДч ПэЛЕ ТОУР ПЯЧТОУР 4 ВАЯАЙТчЯЕР ТОУ ибам СТО ТщКОР.
 * <li>лЕТАТЯщПОУЛЕ ЙэХЕ ЦЯэЛЛА ТОУ ЙЕИЛщМОУ СЕ ДИЬчЖИО АЯИХЛЭ, АЖАИЯЧМТАР АПЭ ТОМ ASCII ВАЯАЙТчЯА
 * ТО 55. ╦ТСИ ЙэХЕ ВАЯАЙТчЯАР НЕЙИМэЕИ АПЭ ТО 10.
 * <li>уПОКОЦъФОУЛЕ ТО УПЭКОИПО ТГР ДИАъЯЕСГР ТОУ ПАЯАПэМЫ ЙЕИЛщМОУ, ПОУ ПКщОМ ЕъМАИ АЯИХЛЭР, АПЭ ТО
 * 97.
 * <li>аМ ТО АПОТщКЕСЛА ЕъМАИ 1, О ибам ЕъМАИ щЦЙУЯОР.</ul>
 * @param string $iban о КОЦАЯИАСЛЭР ибам ВЫЯъР ЙЕМэ, ЛЭМО ЛЕ ВАЯАЙТчЯЕР 0-9а-ф
 * @return bool о КОЦАЯИАСЛЭР IBAN ЕъМАИ щЦЙУЯОР
 * @see is_iban(), is_greek_iban() */
function is_valid_iban($iban) {
	$trg = '';
	foreach(str_split(substr($iban, 4) . substr($iban, 0, 4)) as $c)
		if (ord($c) > 64) $trg .= ord($c) - 55; else $trg .= $c;
	return bcmod($trg, 97) == 1;
}

